practice.solution:
def run_proof(axioms, steps):
    thms = []
    for k in range(len(steps)):
        parts = steps[k].split()
        err = 'error at ' + str(k + 1)
        cmd = parts[0]
        if cmd == 'axiom':
            n = int(parts[1])
            if n < 1 or n > len(axioms):
                return err
            thms.append(axioms[n - 1])
        elif cmd == 'mp':
            m = int(parts[1])
            n = int(parts[2])
            if m < 1 or n < 1 or m > len(thms) or n > len(thms):
                return err
            x = thms[m - 1]
            imp = thms[n - 1]
            if '->' not in imp:
                return err
            a, b = imp.split('->')
            if a != x:
                return err
            thms.append(b)
        elif cmd == 'delete':
            m = int(parts[1])
            if m < 1 or m > len(thms):
                return err
            thms.pop(m - 1)
        else:
            return err
    return thms

