practice.solution:
def best_switch(rate0, horizon, candidates):
    def total(sw):
        when = sw[0]
        if when >= horizon:
            return rate0 * horizon
        t = min(horizon, when + sw[2])
        return when * rate0 + (horizon - t) * sw[1]
    best = rate0 * horizon
    idx = -1
    for i in range(len(candidates)):
        v = total(candidates[i])
        if v > best:
            best = v
            idx = i
    return idx

