practice.solution:
def levin_search(techs):
    total = 0
    for i in range(1, 41):
        for t in techs:
            name = t[0]
            k = t[1]
            steps = t[2]
            if k > i:
                continue
            budget = 2 ** (i - k)
            if steps != -1 and steps <= budget:
                total += steps
                return [i, name, total]
            total += budget
    return [0, 'none', total]

