practice.solution:
def goldbach_pair(n):
    def is_prime(k):
        if k < 2:
            return False
        d = 2
        while d * d <= k:
            if k % d == 0:
                return False
            d += 1
        return True
    p = 2
    while p <= n // 2:
        if is_prime(p) and is_prime(n - p):
            return [p, n - p]
        p += 1
    return []

