practice.solution:
def first_counterexample(limit):
    def is_prime(k):
        if k < 2:
            return False
        d = 2
        while d * d <= k:
            if k % d == 0:
                return False
            d += 1
        return True
    n = 4
    while n <= limit:
        found = False
        p = 2
        while p <= n // 2:
            if is_prime(p) and is_prime(n - p):
                found = True
                break
            p += 1
        if not found:
            return n
        n += 2
    return -1

