practice.solution:
def robot_lifetime(initial, depots):
    fuel = initial
    t = 0
    for d in depots:
        when = d[0]
        if fuel <= 0:
            return t
        if when > t + fuel:
            return t + fuel
        fuel -= when - t
        t = when
        fuel += d[1]
    return t + max(fuel, 0)

