def expectimax(node):
    if not isinstance(node, list):
        return node
    kind = node[0]
    if kind == 'max':
        best = None
        for c in node[1]:
            v = expectimax(c)
            if best is None or v > best:
                best = v
        return best
    total = 0
    for pc in node[1]:
        total += pc[0] * expectimax(pc[1])
    return total

