practice.solution:
def choose_rewrites(cands, budget):
    items = []
    for i in range(len(cands)):
        c = cands[i]
        if c[2]:
            items.append([-c[1], i, c[0], c[3]])
    items.sort()
    left = budget
    out = []
    for it in items:
        if it[3] <= left:
            left -= it[3]
            out.append(it[2])
    return out

